ALTER TABLE public.site_services ADD COLUMN IF NOT EXISTS custom_buttons jsonb NOT NULL DEFAULT '[]'::jsonb, ADD COLUMN IF NOT EXISTS media_type text NOT NULL DEFAULT 'image', ADD COLUMN IF NOT EXISTS quoter_service_id uuid REFERENCES public.quoter_services(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS whatsapp_template text, ADD COLUMN IF NOT EXISTS requires_file boolean NOT NULL DEFAULT false;
ALTER TABLE public.quoter_services ADD COLUMN IF NOT EXISTS has_calculator boolean NOT NULL DEFAULT true, ADD COLUMN IF NOT EXISTS whatsapp_custom_message text, ADD COLUMN IF NOT EXISTS pricing_mode text NOT NULL DEFAULT 'formula', ADD COLUMN IF NOT EXISTS uses_global_vars boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS price_display text NOT NULL DEFAULT 'final', ADD COLUMN IF NOT EXISTS formula text, ADD COLUMN IF NOT EXISTS requires_approval boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS approval_threshold_cop numeric NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS volume_tiers jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE public.quoter_fields ADD COLUMN IF NOT EXISTS formula text, ADD COLUMN IF NOT EXISTS media_url text, ADD COLUMN IF NOT EXISTS media_type text NOT NULL DEFAULT 'image';
CREATE OR REPLACE FUNCTION public.validate_quoter_price_source() RETURNS trigger LANGUAGE plpgsql SET search_path TO 'public' AS $$ BEGIN IF NEW.price_source IS NULL OR NEW.price_source='' THEN NEW.price_source:='fixed'; END IF; IF NEW.price_source !~ '^[a-z][a-z0-9_]{0,79}$' THEN RAISE EXCEPTION 'Origen de precio no válido'; END IF; RETURN NEW; END; $$;